import{z as s,x as o,o as r,c as d,q as B,j as l,D as e,d as a,s as n,S as i,b as A}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"训练配方管理","description":"","frontmatter":{"title":"训练配方管理","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-recipe-management.md","filePath":"llm/ti-recipe-management.md","lastUpdated":1791063341000}'),p={name:"llm/ti-recipe-management.md"};function m(f,E,h,C,D,u){const t=o("Mermaid");return r(),d("div",null,[E[2]||(E[2]=B('<h1 id="训练配方管理" tabindex="-1">训练配方管理 <a class="header-anchor" href="#训练配方管理" aria-label="Permalink to &quot;训练配方管理&quot;">​</a></h1><div class="epigraph"><p>配方是一篇 run 的完整声明：架构、数据、优化、数值、钩子、死线，全部版本化；改一行配置而哈希不变，是一切实验事故的起点。</p><footer>—— 据大规模训练团队的配置管理与复现实践整理</footer></div><p><a href="/llm/ti-failed-exp-archive">上一课</a>把失败写成档案，档案里的死因处处引用判据与配置——那些引用的实体就是本课的主角：训练配方。前几课已多次埋它：<a href="/llm/ti-experiment-tracking">run 身份四元组</a>的首位是配置哈希，<a href="/llm/ti-numerical-health">绊网阈值</a>说好随配方走版本评审，搜索课的响应面最终也落成配方。本课把配方定义清楚并给出管理制度。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>配置管理的反面不是「没有配置文件」，而是<strong>声明不完整与来源不唯一</strong>。不完整：配方只写了学习率与批次数，数值方案、钩子节奏、死线散在启动脚本与个人记忆里——run 出了结果，没人能说出全部自变量。不唯一：同一参数在基础配置、覆盖文件、命令行三处定义，谁覆盖谁靠约定；「顺手改一行没入档」的曲线混进库里，毒化后续对比。还有<strong>变更无痕</strong>：主干配方被直接修改，正在排队复现的人拿到的是新配置，比对实验悄然换底。</p><p><span class="marginnote">直觉类比：配方就像写全克数、火候与步骤的菜谱——只写「盐适量、炒一会儿」的菜谱，做不出第二盘同样的菜。run 的可复现性同理：散在启动脚本和个人记忆里的参数，等于菜谱里没写的「适量」，下次必然变味。</span></p><h3 id="配方的最小字段组" tabindex="-1">配方的最小字段组 <a class="header-anchor" href="#配方的最小字段组" aria-label="Permalink to &quot;配方的最小字段组&quot;">​</a></h3><p>一份完整配方至少六组字段：模型（架构、初始化）、数据（流水线版本、配比、序列长度）、优化（优化器、学习率日程、批次）、数值（精度方案、稳定器、缩放策略）、观测（钩子节奏、绊网阈值、评测计划）、治理（预算死线、止损判据、负责人）。字段组按引用组织：数据组引用流水线版本号而不是内联配比表，优化组的日程写峰值与比例——配方是<strong>指针的集合</strong>，单一事实在数据、数值各课的口径里。</p><p><span class="marginnote">配置哈希必须全链路同一：跟踪系统上报的、检查点元数据写入的、评测报告标注的，是同一哈希函数对同一份物化配置的计算。三处不一致时，涉及这两条 run 的一切对比结论作废——这不是形式洁癖，是可比性的地基。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>管理三条制度。其一，<strong>版本即发布</strong>：配方改动一律升版本号，旧版本只读；「正在跑的作业绑定启动时的版本」沿用数据流水线的物化纪律，在跑作业不受后续修改影响。其二，<strong>评审分级</strong>：改观测组字段（加日志、调绊网）轻评审即可；改优化组与数据组（学习率、配比、序列长度）走正式评审，评审记录挂版本；训练中途改配方被禁止，要改就开新 run。其三，<strong>继承即显式</strong>：家族树形组织（预训练基线 → SFT 变体 → 实验分支），子配方声明父版本与 diff；常用工作负载沉淀为模板，微调的学习率与批次起点可参照<a href="/llm/full-sft-hparams">全参微调的学习率与批次</a>的口径。</p>',11)),(r(),l(i,null,{default:e(()=>[n(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E5%9F%BA%E7%BA%BF%E9%85%8D%E6%96%B9%20v%22%5D%20--%3E%20D1%5B%22%E5%AD%90%E9%85%8D%E6%96%B9%3A%20%E6%98%BE%E5%BC%8F%20diff%20%2B%20%E7%88%B6%E7%89%88%E6%9C%AC%22%5D%0A%20%20D1%20--%3E%20MAT%5B%22%E5%90%AF%E5%8A%A8%E6%97%B6%E7%89%A9%E5%8C%96%3A%20%E8%A7%A3%E6%9E%90%E5%85%A8%E9%83%A8%E5%BC%95%E7%94%A8%E6%88%90%E5%BF%AB%E7%85%A7%22%5D%0A%20%20MAT%20--%3E%20HASH%5B%22%E8%AE%A1%E7%AE%97%E9%85%8D%E7%BD%AE%E5%93%88%E5%B8%8C%22%5D%0A%20%20HASH%20--%3E%20RUN%5B%22%E4%BD%9C%E4%B8%9A%E7%BB%91%E5%AE%9A%3A%20%E8%B7%9F%E8%B8%AA%2F%E6%A3%80%E6%9F%A5%E7%82%B9%2F%E8%AF%84%E6%B5%8B%20%E5%90%8C%E4%B8%80%E5%93%88%E5%B8%8C%22%5D%0A%20%20CH%5B%22%E4%BB%BB%E4%BD%95%E6%94%B9%E5%8A%A8%22%5D%20--%3E%20REV%7B%22%E8%AF%84%E5%AE%A1%E5%88%86%E7%BA%A7%22%7D%0A%20%20REV%20--%3E%7C%E8%A7%82%E6%B5%8B%E7%BB%84%7C%20LIGHT%5B%22%E8%BD%BB%E8%AF%84%E5%AE%A1%2C%20%E5%8D%87%E5%B0%8F%E7%89%88%E6%9C%AC%22%5D%0A%20%20REV%20--%3E%7C%E4%BC%98%E5%8C%96%E6%88%96%E6%95%B0%E6%8D%AE%E7%BB%84%7C%20FULL%5B%22%E6%AD%A3%E5%BC%8F%E8%AF%84%E5%AE%A1%2C%20%E8%AE%B0%E5%BD%95%E6%8C%82%E7%89%88%E6%9C%AC%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A("h2",{id:"机制",tabindex:"-1"},[a("机制 "),A("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=A("p",null,[a("版本化有效的机理是"),A("strong",null,"把自变量空间钉死"),a("：实验的科学性要求「改了什么」有唯一答案，配方版本就是答案；哈希把配置压成可比对的指纹，三个系统的哈希一致才保证指纹没有分叉。物化有效的机理是消除时序耦合：引用的子配置（流水线版本、稳定器阈值）日后都会变，启动时解析成快照，把「引用关系」冻结成「值关系」。继承显式化的机理是控制认知负荷：审一份配方时，评审者要能在几分钟内说出「这条 run 与基线差在哪」，深层覆盖让 diff 不可读，不可读的 diff 就是没被审的 diff。")],-1)),(r(),l(i,null,{default:e(()=>[n(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20B%5B%22%E5%9F%BA%E7%A1%80%E9%85%8D%E7%BD%AE%3A%20%E9%BB%98%E8%AE%A4%E5%80%BC%22%5D%20--%3E%20M%5B%22%E5%90%AF%E5%8A%A8%E6%97%B6%E6%8C%89%E4%BC%98%E5%85%88%E7%BA%A7%E5%90%88%E5%B9%B6%E7%89%A9%E5%8C%96%22%5D%0A%20%20O%5B%22%E8%A6%86%E7%9B%96%E6%96%87%E4%BB%B6%3A%20%E9%A1%B9%E7%9B%AE%E7%BA%A7%22%5D%20--%3E%20M%0A%20%20CL%5B%22%E5%91%BD%E4%BB%A4%E8%A1%8C%3A%20%E5%8D%95%E6%AC%A1%E5%AE%9E%E9%AA%8C%22%5D%20--%3E%20M%0A%20%20M%20--%3E%20H%5B%22%E5%94%AF%E4%B8%80%E5%BF%AB%E7%85%A7%20%2B%20%E5%94%AF%E4%B8%80%E9%85%8D%E7%BD%AE%E5%93%88%E5%B8%8C%22%5D%0A%20%20H%20--%3E%20T%5B%22%E8%B7%9F%E8%B8%AA%20%2F%20%E6%A3%80%E6%9F%A5%E7%82%B9%20%2F%20%E8%AF%84%E6%B5%8B%20%E5%90%8C%E6%BA%90%E5%BC%95%E7%94%A8%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<p><span class="marginnote">术语翻译：物化就是把「指针」在启动那一刻解引用成「值」——配方里写的流水线 v12 只是引用，物化时把 v12 的全部实际内容拷成一份快照。此后上游就算升到 v13、v14，这份快照一动不动，在跑作业读到的永远是启动时的世界。</span></p><p>配方与归档在此闭环：死因档案引用判据原文，判据是配方治理组的字段；配方版本可查，判据才可查，证据链才完整。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>配方管<strong>声明与版本</strong>，不管调参：值从哪来（缩放律、搜索、经验）归机理与搜索课；也不管密钥、路径等环境细节——那属于作业环境与部署配置，两者混在一个文件会让配方既不可读也不安全。过度版本化同样是病：为每次实验建新配方文件让家族树退化成灌木，正确粒度是「语义上的一次方法论变化升一版」，噪声级调参走搜索系统不进主干。</p><p><span class="marginnote">常见误区：初学者容易「为每次实验另存一个新配方文件」，半年后家族树长成几十个说不清辈分的灌木，没人知道该继承哪一份。正确粒度是语义上的一次方法论变化才升一版，噪声级调参交给搜索系统记录，不进主干配方。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>配方六组字段：模型、数据、优化、数值、观测、治理；配方是指针的集合。</li><li>配置哈希全链路同一：跟踪、检查点、评测三处一致是可比性的地基。</li><li>改动即升版，评审分级，训练中途改配方被禁止。</li><li>继承显式声明父版本与 diff，评审者几分钟内能说出与基线的差异。</li><li>出处：据大规模训练配置管理与复现实践整理；调参起点见<a href="/llm/full-sft-hparams">全参微调的学习率与批次</a>。</li></ul>',7))])}const F=s(p,[["render",m]]);export{g as __pageData,F as default};
